program.# The query buttons on their panel. Each:
# Vaicājumu pogas to panelī. Katra nosūta ekrānuzņēmumu uz Google:
#   name: pogas padoms;
#   mode: kurp nonāk ekrānuzņēmums:
#     "ai": Google MI vārdiem atbild uz mini uzvedni virs saviem rezultātiem par
#       attēlu un jautājumu;
#     "chat": pats MI režīms (google.com/ai) programmas logā: programma ieliek tur
#       ekrānuzņēmumu un jautājumu un nosūta tos; logs parādās blakus atlasei tikai ar
#       sarunu un lauku nākamajam jautājumam; ja pogu tur, tā mini uzvednes vietā uzdod
#       jūsu jautājumu balsī, kamēr to tur;
#     "answer": tas pats, bet logs ir paslēpts: atbilde tiek parādīta kartītē blakus
#       atlasei;
#     "images": meklēšana pēc attēla bez jautājuma, programmas logā blakus atlasei:
#       uzreiz precīzās atbilstības — lapas ar tieši šo attēlu, kuru virsrakstos bieži
#       ir teikts, kas tajā redzams;
#   prompt: mini uzvedne, jautājums MI, režīmiem "ai", "chat" un "answer";
#   key: pogas taustiņš, kamēr ekrāns ir iesaldēts;
#   icon: "google", "translate", "images" vai "question".
# MI pogas panelī stāv pirmās, meklēšana pēc attēla — aiz tām.
# Google kontā pierakstās programmas logā no iestatījumu loga sadaļas „Google konts“;
# kamēr neviens nav pierakstījies, programma startējot piedāvā pierakstīties.
